def halve(n):               # O(log n): cut the range in half each time
    steps = 0
    while n > 1:
        n //= 2
        steps += 1
    return steps

def all_pairs(arr):         # O(n²): two nested loops
    for a in arr:
        for b in arr:
            print(a, b)

def fib(n):                 # O(2ⁿ): every call makes two more calls
    return n if n < 2 else fib(n - 1) + fib(n - 2)

def bubble_sort(arr):
    n = len(arr)
    for i in range(n):
        swapped = False
        for j in range(n - 1 - i):
            if arr[j] > arr[j + 1]:
                arr[j], arr[j + 1] = arr[j + 1], arr[j]
                swapped = True
        if not swapped:      # a pass with no swap means it is sorted, so stop early
            break

def total(nums):            # extra space O(1)
    result = 0              # just one extra variable
    for x in nums:
        result += x
    return result

def doubled(nums):          # extra space O(n)
    return [x * 2 for x in nums]   # builds a new list of length n

def factorial(n):
    if n <= 1:
        return 1
    return n * factorial(n - 1)
